	@Override
    public void onBar(Instrument instrument, Period period, IBar askBar, IBar bidBar) throws JFException {
		try {
			if(instrument != this.selectedInstrument || period != this.selectedPeriod){
				return;
			}
			
			time = history.getStartTimeOfCurrentBar(instrument, period);

			if(context.getDataService().isOfflineTime(time)) return;
			
			sqManageOrders();
		
			openingOrdersAllowed = sqHandleTradingOptions();
		
   //------------------------
   // Rule: Daily Reset
   //------------------------
   if ((SQTime.getDayOfWeek(getBarTime("Current", 0, 0)) != SQTime.getDayOfWeek(getBarTime("Current", 0, 1))))
   {
      // Action #1
      barcount = (int) AssignVrbVleEntMlt1;

      // Action #2
      Rangeready = (boolean) (false);

      // Action #3
      h = (double) AssignVrbVleEntMlt1;

      // Action #4
      l = (double) AssignVrbVleEntMlt1;

      // Action #5
      SL = (double) AssignVrbVleEntMlt1;

      // Action #6
      TP_Active = (int) AssignVrbVleEntMlt1;

  }

                
   //------------------------
   // Rule: InitRange
   //------------------------
   if ((((barcount == 0)
      && (SQTime.getHour(getBarTime("Current", 0, 0)) == 8))
      && (SQTime.getMinute(getBarTime("Current", 0, 0)) >= 1)))
   {
      // Action #1
      h = (double) sqHigh("Current", 0, 1);

      // Action #2
      l = (double) sqLow("Current", 0, 1);

      // Action #3
      barcount = (int) AssignVrbVleEntMlt2;

      // Action #4
      Rangeready = (boolean) (false);

  }

                
   //------------------------
   // Rule: UpdateRange
   //------------------------
   if (((!(Rangeready))
      && ((barcount < Openrangeminutes)
      && (barcount > 0))))
   {
      // Action #1
      h = (double) MathMax(h, sqHigh("Current", 0, 0));

      // Action #2
      l = (double) MathMin(l, sqLow("Current", 0, 0));

      // Action #3
      barcount = (int) (barcount + AssignVrbVleEntMlt2);

  }

                
   //------------------------
   // Rule: TSL0
   //------------------------
   if ((((!(Rangeready))
      && (barcount == Openrangeminutes))
      && (tsl_mode == 0)))
   {
      // Action #1
      TSL = (double) AssignVrbVleEntMlt3;

  }

                
   //------------------------
   // Rule: TSL1
   //------------------------
   if ((((!(Rangeready))
      && (barcount == Openrangeminutes))
      && (tsl_mode == 1)))
   {
      // Action #1
      TSL = (double) AssignVrbVleEntMlt4;

  }

                
   //------------------------
   // Rule: TSL2
   //------------------------
   if ((((!(Rangeready))
      && (barcount == Openrangeminutes))
      && (tsl_mode == 2)))
   {
      // Action #1
      TSL = (double) AssignVrbVleEntMlt2;

  }

                
   //------------------------
   // Rule: TSL3
   //------------------------
   if ((((!(Rangeready))
      && (barcount == Openrangeminutes))
      && (tsl_mode == 3)))
   {
      // Action #1
      TSL = (double) AssignVrbVleEntMlt5;

  }

                
   //------------------------
   // Rule: TP_Threshold0
   //------------------------
   if ((((!(Rangeready))
      && (barcount == Openrangeminutes))
      && (tsl_mode == 0)))
   {
      // Action #1
      TP_threshold_factor = (double) AssignVrbVleEntMlt3;

  }

                
   //------------------------
   // Rule: TP_Threshold1
   //------------------------
   if ((((!(Rangeready))
      && (barcount == Openrangeminutes))
      && (tsl_mode == 1)))
   {
      // Action #1
      TP_threshold_factor = (double) AssignVrbVleEntMlt4;

  }

                
   //------------------------
   // Rule: TP_Threshold2
   //------------------------
   if ((((!(Rangeready))
      && (barcount == Openrangeminutes))
      && (tsl_mode == 2)))
   {
      // Action #1
      TP_threshold_factor = (double) AssignVrbVleEntMlt2;

  }

                
   //------------------------
   // Rule: TP_Threshold3
   //------------------------
   if ((((!(Rangeready))
      && (barcount == Openrangeminutes))
      && (tsl_mode == 3)))
   {
      // Action #1
      TP_threshold_factor = (double) AssignVrbVleEntMlt2;

  }

                
   //------------------------
   // Rule: RDD0
   //------------------------
   if ((((!(Rangeready))
      && (barcount == Openrangeminutes))
      && (RDD_mode == 0)))
   {
      // Action #1
      RDD_factor = (double) AssignVrbVleEntMlt3;

  }

                
   //------------------------
   // Rule: RDD1
   //------------------------
   if ((((!(Rangeready))
      && (barcount == Openrangeminutes))
      && (RDD_mode == 1)))
   {
      // Action #1
      RDD_factor = (double) AssignVrbVleEntMlt4;

  }

                
   //------------------------
   // Rule: RDD2
   //------------------------
   if ((((!(Rangeready))
      && (barcount == Openrangeminutes))
      && (RDD_mode == 2)))
   {
      // Action #1
      RDD_factor = (double) AssignVrbVleEntMlt2;

  }

                
   //------------------------
   // Rule: RDD3
   //------------------------
   if ((((!(Rangeready))
      && (barcount == Openrangeminutes))
      && (RDD_mode == 3)))
   {
      // Action #1
      RDD_factor = (double) AssignVrbVleEntMlt5;

  }

                
   //------------------------
   // Rule: FreezeRange
   //------------------------
   if (((!(Rangeready))
      && (barcount >= Openrangeminutes)))
   {
      // Action #1
      sigma = (double) sqStdDev("Current", 0, Openrangeminutes, 0, MODE_SMA, CLOSE, 1);

      // Action #2
      Bu = (double) (h + (epsilon1 * sigma));

      // Action #3
      Bl = (double) (l - (epsilon2 * sigma));

      // Action #4
      SL = (double) (TSL * (Bu - Bl));

      // Action #5
      Rangeready = (boolean) (true);

  }

                
   //------------------------
   // Rule: Trading signals
   //------------------------
	LongEntrySignal = ((((Rangeready
      && (sqHigh("Current", 0, 1) > Bu))
      && (SQTime.getHour(getBarTime("Current", 0, 0)) >= 8))
      && (SQTime.getMinute(getBarTime("Current", 0, 0)) >= 30))
      && (SQTime.getHour(getBarTime("Current", 0, 0)) < 16));
	ShortEntrySignal = ((((Rangeready
      && (sqLow("Current", 0, 1) < Bl))
      && (SQTime.getHour(getBarTime("Current", 0, 0)) >= 8))
      && (SQTime.getMinute(getBarTime("Current", 0, 0)) >= 30))
      && (SQTime.getHour(getBarTime("Current", 0, 0)) < 16));
	LongExitSignal = false;
	ShortExitSignal = false;


                
   //------------------------
   // Rule: Long entry
   //------------------------
   if ((LongEntrySignal
      && sqMarketPositionIsFlat(MagicNumber, "Current", "")))
   {
      // Action #1
         order = sqOpenOrder(BUY, "Current", mmLots, 0, MagicNumber, "", 0, false, false, null, false);

      if(order != null) {
		 ticket = order.getLabel();
	  
         // set or initialize all order exit methods (SL, PT, Trailing Stop, Exit After Bars, etc.)
         // StopLoss & ProfitTarget
         sqSetSLandPT(order, sqGetSLLevel("Current", BUY, 0, 3, (sqGetOrderOpenPrice("Current", MagicNumber, 1, "") - SL)), 0);

      }


      // Action #2
      max_price = (double) sqGetOrderOpenPrice("Current", MagicNumber, 1, "");

  }

                
   //------------------------
   // Rule: Short entry
   //------------------------
   if ((ShortEntrySignal
      && sqMarketPositionIsFlat(MagicNumber, "Current", "")))
   {
      // Action #1
         order = sqOpenOrder(SELL, "Current", mmLots, 0, MagicNumber, "", 0, false, false, null, false);

      if(order != null) {
		 ticket = order.getLabel();
	  
         // set or initialize all order exit methods (SL, PT, Trailing Stop, Exit After Bars, etc.)
         // StopLoss & ProfitTarget
         sqSetSLandPT(order, sqGetSLLevel("Current", SELL, 0, 3, (sqGetOrderOpenPrice("Current", MagicNumber, -1, "") + SL)), 0);

      }


      // Action #2
      min_price = (double) sqGetOrderOpenPrice("Current", MagicNumber, -1, "");

  }

                
   //------------------------
   // Rule: Upadte_Max_price
   //------------------------
   if ((sqGetMarketPosition("Current", MagicNumber, "") != 0))
   {
      // Action #1
      max_price = (double) MathMax(max_price, sqHigh("Current", 0, 0));

      // Action #2
      min_price = (double) MathMin(min_price, sqLow("Current", 0, 0));

  }

                
   //------------------------
   // Rule: Activate_TP
   //------------------------
   if ((((sqGetMarketPosition("Current", MagicNumber, "") > 0)
      && (TP_Active == 0))
      && ((sqClose("Current", 0, 0) - sqGetOrderOpenPrice("Current", MagicNumber, 1, "")) >= (TP_threshold_factor * (Bu - Bl)))))
   {
      // Action #1
      TP_Active = (int) AssignVrbVleEntMlt2;

  }

                
   //------------------------
   // Rule: Activate_TP_short
   //------------------------
   if ((((sqGetMarketPosition("Current", MagicNumber, "") < 0)
      && (TP_Active == 0))
      && ((sqGetOrderOpenPrice("Current", MagicNumber, -1, "") - sqClose("Current", 0, 0)) >= (TP_threshold_factor * (Bu - Bl)))))
   {
      // Action #1
      TP_Active = (int) AssignVrbVleEntMlt2;

  }

                
   //------------------------
   // Rule: Exit_RDD
   //------------------------
   if (((((TP_Active == 1)
      && (sqGetBarsSinceOpen("Current", MagicNumber, 0, "") > 0))
      && (((sqClose("Current", 0, 0) <= (max_price - (RDD_factor * (max_price - sqGetOrderOpenPrice("Current", MagicNumber, 1, "")))))
      && (sqGetMarketPosition("Current", MagicNumber, "") > 0))
      ||  ((sqClose("Current", 0, 0) >= (min_price + (RDD_factor * (sqGetOrderOpenPrice("Current", MagicNumber, -1, "") - min_price))))
      && (sqGetMarketPosition("Current", MagicNumber, "") < 0))))
      && (sqGetOpenPLInPips("Current", MagicNumber, 0, "") > 0)))
   {
      // Action #1
      // Close all positions
      sqCloseAllPositions("Current", MagicNumber, 0, "");

      // Action #2
      TP_Active = (int) AssignVrbVleEntMlt1;

  }

                
		} catch(Exception e) {
			print(String.format("ERROR: %s", e.getMessage()));			
			errors++;

			throw e;
		}
    }
	
