private double sqGetValueByIdentification(int idHash, Instrument instrument) throws JFException {

   if(idHash == sqStringHash("0")) {
      return 0;
   }

   if(idHash == sqStringHash("0")) {
      return 0;
   }

   if(idHash == sqStringHash("0")) {
      return 0;
   }

   if(idHash == sqStringHash("(sqGetOrderOpenPrice(Current, MagicNumber, 1, ) - SL)")) {
      return (sqGetOrderOpenPrice("Current", MagicNumber, 1, "") - SL);
   }

   if(idHash == sqStringHash("0")) {
      return 0;
   }

   if(idHash == sqStringHash("0")) {
      return 0;
   }

   if(idHash == sqStringHash("0")) {
      return 0;
   }

   if(idHash == sqStringHash("0")) {
      return 0;
   }

   if(idHash == sqStringHash("0")) {
      return 0;
   }

   if(idHash == sqStringHash("(sqGetOrderOpenPrice(Current, MagicNumber, -1, ) + SL)")) {
      return (sqGetOrderOpenPrice("Current", MagicNumber, -1, "") + SL);
   }

   if(idHash == sqStringHash("0")) {
      return 0;
   }

   if(idHash == sqStringHash("0")) {
      return 0;
   }

   return 0;
}
	
